const matches = $json.matches || [];
const pos = $('Приём позиции').item.json.body || {};
const norms = matches.map((m, i) => `[${i+1}] ${(m.metadata && m.metadata.glava) || ''}${(m.metadata && m.metadata.punkt) ? (' п.' + m.metadata.punkt) : ''}: ${(m.metadata && m.metadata.text) || ''}`).join('\n\n');
const prompt = `см. prompts/03-classification-prompt.md — полный шаблон промпта с найденными нормами и данными затраты`;
return { json: { prompt: prompt, norms_count: matches.length } };

const doc = $('Приём позиции').item.json.body || {};
const resp = $json;
let text = '';
try { text = resp.candidates[0].content.parts[0].text; } catch (e) {}
let data = {};
try { data = JSON.parse(text); } catch (e) { data = { признак: 'спорно', обоснование: 'Модель вернула нечитаемый ответ' }; }
return { json: {
  doc_id: doc.doc_id || null,
  position: doc.text || null,
  amount: doc.amount || null,
  classification: data,
  needs_review: (data.признак !== 'учитывается') || ((data.confidence != null) && data.confidence < 0.8),
  model: 'gemini-2.5-flash'
} };
